import React, { useState, useEffect } from 'react';
import { 
  User, Lock, Eye, EyeOff, ArrowRight, 
  Globe, Radio, ShieldAlert,
  Fingerprint, Sparkles, Activity,
  BellRing, X, RefreshCw, Smartphone,
  BadgeCheck, KeyRound, Briefcase, 
  Zap, ChevronRight, LayoutDashboard, Wallet,
  Building2, UserCircle,
  AlertCircle, Monitor,
  Apple,
  Chrome
} from 'lucide-react';
import { SurePathLogo } from './Navbar';
import { Language, UserRole } from '../types';
import { db, seedDatabase, User as DBUser } from '../db';
import { hashPassword, verifyPassword } from '../services/authService';
import { NeuralBot } from './car-wizard/WizardUI';

interface AuthGateProps {
  onAuthSuccess: (user: any) => void;
  initialLang?: Language;
}

const InputField = ({ icon: Icon, label, type, value, onChange, showPass, setShowPass, placeholder, status }: any) => (
  <div className="space-y-2 group animate-fade-in">
    <div className="flex justify-between items-center px-1">
      <label className="text-[0.65rem] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest group-focus-within:text-primary-500 transition-colors">
        {label}
      </label>
      {status === 'valid' && <CheckCircle2 size={12} className="text-emerald-500 animate-pop-in" />}
    </div>
    <div className="relative">
      <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-primary-500 transition-all">
        <Icon size={20} strokeWidth={2.5} />
      </div>
      <input 
        type={type === 'password' && showPass ? 'text' : type}
        placeholder={placeholder}
        required
        className="w-full pl-12 pr-12 py-4.5 bg-slate-50 dark:bg-white/[0.02] border-2 border-slate-100 dark:border-white/5 rounded-2xl outline-none transition-all font-bold text-sm text-slate-900 dark:text-white placeholder:text-slate-300 focus:border-primary-500 focus:bg-white dark:focus:bg-black/40 shadow-inner"
        value={value}
        onChange={(e) => onChange(e.target.value)}
      />
      {type === 'password' && (
        <button 
          type="button"
          onClick={() => setShowPass(!showPass)}
          className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300 hover:text-primary-500 p-2 transition-colors"
        >
          {showPass ? <EyeOff size={18}/> : <Eye size={18}/>}
        </button>
      )}
    </div>
  </div>
);

const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.ID }) => {
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'VERIFY' | 'DEMO_SELECT'>('LOGIN');
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [showIncomingOtp, setShowIncomingOtp] = useState(false);
  const [statusMsg, setStatusMsg] = useState('Neural Secure Protocol v4.2');

  const [formData, setFormData] = useState({ name: '', email: '', phone: '', password: '' });

  useEffect(() => {
    seedDatabase();
  }, []);

  const handleQuickDemo = async (email: string) => {
    setLoading(true);
    setStatusMsg('Authenticating Access Node...');
    try {
      const user = await db.users.where('email').equals(email).first();
      if (user) {
        setTimeout(() => onAuthSuccess(user), 1200);
      } else {
        setError("Node ID not found in registry.");
        setLoading(false);
      }
    } catch (err) {
      setError("Network handshake failed.");
      setLoading(false);
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setStatusMsg('Decrypting credentials...');

    try {
      if (mode === 'LOGIN') {
        const user = await db.users.where('email').equals(formData.email).first();
        if (user && user.passwordHash && user.salt) {
          const isValid = await verifyPassword(formData.password, user.passwordHash, user.salt);
          if (isValid) {
            setStatusMsg('Handshake successful!');
            setTimeout(() => onAuthSuccess(user), 800);
          } else {
            setError("Invalid encryption key or ID.");
            setLoading(false);
          }
        } else {
          setError("Subscriber node not registered.");
          setLoading(false);
        }
      } else {
        const existing = await db.users.where('email').equals(formData.email).first();
        if (existing) {
          setError("Email already has an active node.");
          setLoading(false);
          return;
        }
        const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
        setGeneratedOtp(newOtp);
        setTimeout(() => {
          setMode('VERIFY');
          setLoading(false);
          setShowIncomingOtp(true);
          setStatusMsg('Verification Code Sent');
        }, 1500);
      }
    } catch (err) {
      setError("System kernel timeout.");
      setLoading(false);
    }
  };

  const finalizeRegistration = async () => {
    setLoading(true);
    setStatusMsg('Generating Neural ID...');
    try {
      const { hash, salt } = await hashPassword(formData.password);
      const newUser: DBUser = {
        name: formData.name,
        email: formData.email,
        phone: formData.phone,
        passwordHash: hash,
        salt: salt,
        role: UserRole.CUSTOMER,
        nodeId: `SP-NODE-${Math.floor(1000 + Math.random() * 9000)}`,
        verified: true,
        trustScore: 85,
        memberSince: new Date().toISOString()
      };
      const id = await db.users.add(newUser);
      onAuthSuccess({ ...newUser, id });
    } catch (err) {
      setError("Failed to create node.");
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#fafaf9] dark:bg-[#050505] flex flex-col items-center p-6 relative overflow-hidden transition-colors duration-1000">

      {/* Dynamic Immersive Background */}
      <div className="absolute inset-0 pointer-events-none z-0">
        <div className="absolute top-[-10%] right-[-10%] w-[500px] h-[500px] bg-primary-500/10 rounded-full blur-[100px] animate-pulse"></div>
        <div className="absolute bottom-[-10%] left-[-10%] w-[400px] h-[400px] bg-emerald-500/10 rounded-full blur-[100px] animate-pulse animation-delay-2000"></div>
        <div className="absolute inset-0 bg-neural-mesh opacity-30 dark:opacity-10"></div>
      </div>

      {/* Mock Incoming OTP Notification */}
      {showIncomingOtp && (
        <div className="fixed top-8 left-6 right-6 z-[500] animate-pop-in">
           <div className="bg-slate-900/90 backdrop-blur-2xl rounded-3xl p-6 shadow-2xl flex items-center gap-6 border border-white/10 ring-1 ring-white/20">
              <div className="w-14 h-14 bg-primary-500 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-primary-500/30">
                <BellRing size={28} className="animate-bounce" />
              </div>
              <div className="flex-1">
                 <p className="text-[0.6rem] font-black text-primary-400 uppercase tracking-widest mb-1">Incoming Verification Code</p>
                 <div className="flex items-center gap-4">
                    <span className="text-3xl font-black text-white tracking-[0.3em] font-mono">{generatedOtp}</span>
                    <button onClick={() => { setOtp(generatedOtp); setShowIncomingOtp(false); }} className="ml-auto px-5 py-2 bg-primary-500 text-white rounded-xl text-[0.6rem] font-black uppercase tracking-widest hover:scale-105 active:scale-95 transition-all">Auto-Fill</button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* Header Info */}
      <div className="w-full flex items-center justify-between mb-6 z-50">
        <div className="flex items-center gap-3">
          <div className="w-2 h-2 rounded-full bg-primary-500 animate-ping shadow-[0_0_8px_#f97316]"></div>
          <p className="text-[0.6rem] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest">{statusMsg}</p>
        </div>
        <div className="flex items-center gap-2">
           <Globe size={14} className="text-slate-300"/>
           <span className="text-[0.6rem] font-black uppercase text-slate-400 tracking-widest">Global Node</span>
        </div>
      </div>

      {/* Main Form Container */}
      <div className="w-full max-w-md flex flex-col items-center space-y-8 flex-1 relative z-10">

        {/* Branding & Bot */}
        <div className="flex flex-col items-center text-center">
          <div className="relative mb-6">
            <div className="p-7 bg-white dark:bg-[#0f172a] rounded-[2.8rem] shadow-2xl border border-slate-100 dark:border-white/5 relative group transition-all duration-700 hover:rotate-2">
               <SurePathLogo className="w-20 h-20 relative z-10 drop-shadow-xl" />
            </div>
            <div className="absolute -bottom-4 -right-4 w-14 h-14 bg-white dark:bg-slate-900 rounded-2xl shadow-xl border border-black/5 dark:border-white/10 flex items-center justify-center">
               <NeuralBot mood={loading ? 'thinking' : formData.email ? 'happy' : 'scanning'} className="w-10 h-10" />
            </div>
          </div>
          <h1 className="text-4xl font-black tracking-tight uppercase text-slate-900 dark:text-white leading-none">Sure<span className="text-primary-500">Path</span></h1>
          <p className="text-[0.65rem] font-bold text-slate-400 dark:text-gray-500 uppercase tracking-[0.4em] mt-3">Identity Access Management</p>
        </div>

        {/* Content Box */}
        <div className="w-full bg-white/70 dark:bg-black/30 backdrop-blur-2xl rounded-[3.5rem] p-1 shadow-[0_30px_60px_-12px_rgba(0,0,0,0.12)] border border-white dark:border-white/5 overflow-hidden">
          <div className="bg-white dark:bg-[#0a0a0a]/60 rounded-[3.4rem] p-8 space-y-8">
            {mode === 'DEMO_SELECT' ? (
              <div className="space-y-6 animate-pop-in">
                 <div className="flex justify-between items-center px-2">
                    <h3 className="font-black uppercase tracking-widest text-sm text-primary-500">Pathfinder Access</h3>
                    <button onClick={() => setMode('LOGIN')} className="p-2.5 bg-gray-50 dark:bg-white/5 rounded-xl hover:text-rose-500 transition-all"><X size={18}/></button>
                 </div>

                 <div className="space-y-4">
                   <button onClick={() => handleQuickDemo('user@surepath.ai')} className="w-full p-6 bg-blue-500/5 dark:bg-blue-500/10 rounded-[2.5rem] border-2 border-blue-500/20 text-left flex items-center gap-5 group hover:border-blue-500 hover:bg-blue-500/[0.02] transition-all">
                      <div className="w-14 h-14 bg-blue-500 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-blue-500/30 group-hover:scale-110 transition-transform"><UserCircle size={28}/></div>
                      <div className="flex-1">
                        <p className="font-black text-slate-900 dark:text-white uppercase tracking-tighter">Member Portal</p>
                        <p className="text-[0.6rem] font-bold text-blue-500 uppercase tracking-widest">End-User Application Node</p>
                      </div>
                      <ChevronRight size={20} className="text-blue-500 opacity-0 group-hover:opacity-100 group-hover:translate-x-1 transition-all"/>
                   </button>

                   <button onClick={() => handleQuickDemo('agent@surepath.ai')} className="w-full p-6 bg-emerald-500/5 dark:bg-emerald-500/10 rounded-[2.5rem] border-2 border-emerald-500/20 text-left flex items-center gap-5 group hover:border-emerald-500 hover:bg-emerald-500/[0.02] transition-all">
                      <div className="w-14 h-14 bg-emerald-500 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-emerald-500/30 group-hover:scale-110 transition-transform"><Briefcase size={28}/></div>
                      <div className="flex-1">
                        <p className="font-black text-slate-900 dark:text-white uppercase tracking-tighter">Partner Node</p>
                        <p className="text-[0.6rem] font-bold text-emerald-500 uppercase tracking-widest">Agent Ledger & CMS</p>
                      </div>
                      <ChevronRight size={20} className="text-emerald-500 opacity-0 group-hover:opacity-100 group-hover:translate-x-1 transition-all"/>
                   </button>
                 </div>
              </div>
            ) : mode === 'VERIFY' ? (
              <div className="space-y-8 text-center animate-pop-in py-6">
                <div className="space-y-2">
                  <div className="w-16 h-16 bg-primary-500/10 rounded-2xl flex items-center justify-center text-primary-500 mx-auto mb-4">
                    <ShieldCheck size={32}/>
                  </div>
                  <h3 className="text-2xl font-black uppercase tracking-tight">Confirm Registry</h3>
                  <p className="text-xs text-slate-500 font-bold uppercase tracking-widest px-4">Enter the 6-digit decryption key sent to your terminal.</p>
                </div>
                <input 
                  type="tel" maxLength={6} placeholder="000000"
                  className="w-full bg-transparent border-b-4 border-slate-200 dark:border-white/10 text-center text-5xl font-black tracking-[0.4em] text-primary-500 outline-none focus:border-primary-500 transition-all font-mono"
                  value={otp} onChange={(e) => { setOtp(e.target.value.replace(/\D/g,'')); setError(null); }}
                />
                <div className="space-y-4 pt-4">
                  <button 
                    onClick={async () => otp === generatedOtp ? await finalizeRegistration() : setError("Mismatched security key.")} 
                    disabled={otp.length < 6 || loading} 
                    className="w-full py-5 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-sm tracking-[0.3em] shadow-2xl active:scale-95 disabled:opacity-30 transition-all"
                  >
                    Authenticate Node
                  </button>
                  <button className="text-[0.6rem] font-black text-slate-400 uppercase tracking-widest hover:text-primary-500 transition-colors">Resend Code (59s)</button>
                </div>
              </div>
            ) : (
              <form onSubmit={handleAuth} className="space-y-6">
                {/* Mode Switcher */}
                <div className="flex bg-slate-100 dark:bg-white/[0.05] p-1.5 rounded-2xl border border-slate-200/50 dark:border-white/5 shadow-inner">
                  <button type="button" onClick={() => { setMode('LOGIN'); setError(null); }} className={`flex-1 py-3.5 rounded-[0.9rem] text-[0.65rem] font-black uppercase tracking-[0.2em] transition-all ${mode === 'LOGIN' ? 'bg-white dark:bg-slate-700 text-primary-600 shadow-md scale-100' : 'text-gray-400 opacity-60 scale-95'}`}>Sign In</button>
                  <button type="button" onClick={() => { setMode('REGISTER'); setError(null); }} className={`flex-1 py-3.5 rounded-[0.9rem] text-[0.65rem] font-black uppercase tracking-[0.2em] transition-all ${mode === 'REGISTER' ? 'bg-white dark:bg-slate-700 text-primary-600 shadow-md scale-100' : 'text-gray-400 opacity-60 scale-95'}`}>Sign Up</button>
                </div>

                <div className="space-y-5">
                  {mode === 'REGISTER' && (
                    <InputField icon={User} label="Full Legal Name" value={formData.name} onChange={(v:any)=>setFormData({...formData, name: v})} placeholder="Sesuai KTP" status={formData.name.length > 3 ? 'valid' : ''} />
                  )}
                  <InputField icon={Globe} label="Access ID (Email)" type="email" value={formData.email} onChange={(v:any)=>setFormData({...formData, email: v})} placeholder="email@surepath.ai" status={formData.email.includes('@') ? 'valid' : ''} />
                  <InputField icon={KeyRound} label="Security Passkey" type="password" value={formData.password} onChange={(v:any)=>setFormData({...formData, password: v})} showPass={showPass} setShowPass={setShowPass} placeholder="••••••••" />
                </div>

                {error && (
                  <div className="p-4 bg-rose-500/10 border border-rose-500/20 rounded-2xl text-rose-500 text-[0.65rem] font-black uppercase tracking-widest text-center animate-pop-in flex items-center justify-center gap-2">
                    <AlertCircle size={14}/> {error}
                  </div>
                )}

                <div className="space-y-4 pt-2">
                  <button type="submit" disabled={loading} className="w-full py-5 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-sm tracking-[0.25em] shadow-2xl hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-4 relative overflow-hidden group">
                     {loading && <div className="absolute inset-0 bg-primary-500/10 animate-pulse"></div>}
                     {loading ? <RefreshCw size={22} className="animate-spin text-primary-500"/> : (mode === 'LOGIN' ? 'Initiate Access' : 'Create Node')} 
                     {!loading && <ArrowRight size={22} className="text-primary-500 group-hover:translate-x-1 transition-transform"/>}
                  </button>

                  {/* Social Login Visuals */}
                  <div className="relative py-4 flex items-center justify-center">
                    <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-100 dark:border-white/5"></div></div>
                    <span className="relative px-4 bg-white dark:bg-[#0a0a0a] text-[0.55rem] font-black text-gray-400 uppercase tracking-widest">Or authenticate via</span>
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <button type="button" className="py-4 border border-black/5 dark:border-white/5 bg-gray-50 dark:bg-white/[0.02] rounded-2xl flex items-center justify-center gap-3 hover:bg-white transition-all active:scale-95 shadow-sm">
                       <Apple size={18} className="dark:text-white" />
                       <span className="text-[0.65rem] font-black uppercase tracking-widest">Apple</span>
                    </button>
                    <button type="button" className="py-4 border border-black/5 dark:border-white/5 bg-gray-50 dark:bg-white/[0.02] rounded-2xl flex items-center justify-center gap-3 hover:bg-white transition-all active:scale-95 shadow-sm">
                       <Chrome size={18} className="text-blue-500" />
                       <span className="text-[0.65rem] font-black uppercase tracking-widest">Google</span>
                    </button>
                  </div>

                  <button type="button" onClick={() => setMode('DEMO_SELECT')} className="w-full py-5 bg-primary-500/10 text-primary-600 dark:text-primary-400 border border-primary-500/20 rounded-2xl font-black uppercase text-[0.7rem] tracking-[0.2em] hover:bg-primary-500 hover:text-white transition-all flex items-center justify-center gap-3 active:scale-95">
                    <Zap size={14} fill="currentColor" className="animate-pulse"/> Switch to Pathfinder Demo
                  </button>
                </div>
              </form>
            )}
          </div>
        </div>

        {/* Biometric Integration Visual */}
        <div className="flex flex-col items-center gap-4 opacity-40 py-6 transition-all hover:opacity-100 cursor-pointer group">
           <div className="w-16 h-16 rounded-[1.5rem] border-2 border-dashed border-slate-300 dark:border-white/20 flex items-center justify-center text-slate-400 group-hover:border-primary-500 group-hover:text-primary-500 transition-all group-hover:scale-110 duration-500">
              <Fingerprint size={32} strokeWidth={1.5} />
           </div>
           <p className="text-[0.6rem] font-black uppercase tracking-[0.3em] text-center leading-relaxed">
             Tap to authorize <br/> with Bio-Metric ID
           </p>
        </div>

        {/* Trust Badges */}
        <div className="flex items-center gap-10 opacity-30 pb-10">
           <div className="flex items-center gap-2"><BadgeCheck size={16} className="text-emerald-500"/><span className="text-[0.6rem] font-black uppercase tracking-widest">OJK Certified</span></div>
           <div className="flex items-center gap-2"><ShieldAlert size={16} className="text-blue-500"/><span className="text-[0.6rem] font-black uppercase tracking-widest">AES-256 Vault</span></div>
        </div>
      </div>
    </div>
  );
};

export default AuthGate;

import React from 'react';
import { Cpu, Zap, ShieldCheck, Activity, Radio, Globe, Terminal } from 'lucide-react';

// Reusable Page Transition Wrapper
export const PageTransition: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="animate-pop-in w-full h-full">
    {children}
  </div>
);

// Reusable Neural Bot Component 2.0 - More Premium
export const NeuralBot = ({ 
  className = "w-24 h-24", 
  mood = "scanning",
  color = "emerald" 
}: { 
  className?: string, 
  mood?: 'happy' | 'thinking' | 'scanning' | 'wave',
  color?: 'emerald' | 'blue' | 'rose' | 'amber' | 'slate' | 'indigo' | 'purple'
}) => {
  const colorMap = {
    emerald: '#10b981',
    blue: '#3b82f6',
    rose: '#f43f5e',
    amber: '#f59e0b',
    slate: '#64748b',
    indigo: '#6366f1',
    purple: '#a855f7'
  };

  const accentColor = colorMap[color] || colorMap.emerald;

  return (
    <svg viewBox="0 0 200 200" className={className} fill="none" xmlns="http://www.w3.org/2000/svg">
      <defs>
        <linearGradient id="botChassis" x1="0" y1="0" x2="200" y2="200">
          <stop offset="0%" stopColor="#ffffff" />
          <stop offset="100%" stopColor="#eef2ff" />
        </linearGradient>
        <filter id="botShadow" x="-20%" y="-20%" width="140%" height="140%">
          <feDropShadow dx="0" dy="10" stdDeviation="15" floodColor="rgba(0,0,0,0.1)" />
        </filter>
        <radialGradient id="eyeGlow" cx="50%" cy="50%" r="50%">
          <stop offset="0%" stopColor={accentColor} />
          <stop offset="100%" stopColor="transparent" />
        </radialGradient>
      </defs>

      <g className="animate-float" filter="url(#botShadow)">
        {/* Main Chassis */}
        <rect x="30" y="40" width="140" height="120" rx="55" fill="url(#botChassis)" stroke="#d1d5db" strokeWidth="1" />

        {/* Inner Screen Surface */}
        <rect x="45" y="65" width="110" height="65" rx="25" fill="#0f172a" />

        {/* Interactive Face */}
        <g className={mood === 'scanning' ? 'animate-pulse' : ''}>
          {(mood === 'happy' || mood === 'wave') && (
            <>
              <circle cx="75" cy="95" r="10" fill="url(#eyeGlow)" opacity="0.3" className="animate-pulse" />
              <circle cx="125" cy="95" r="10" fill="url(#eyeGlow)" opacity="0.3" className="animate-pulse" />
              <circle cx="75" cy="95" r="5" fill={accentColor} />
              <circle cx="125" cy="95" r="5" fill={accentColor} />
              <path d="M 80 115 Q 100 125 120 115" stroke={accentColor} strokeWidth="5" strokeLinecap="round" />
            </>
          )}
          {mood === 'scanning' && (
            <>
               <rect x="60" y="92" width="30" height="6" rx="3" fill={accentColor} />
               <rect x="110" y="92" width="30" height="6" rx="3" fill={accentColor} />
               <rect x="50" y="80" width="100" height="30" rx="8" fill={accentColor} opacity="0.1" />
               <line x1="50" y1="95" x2="150" y2="95" stroke={accentColor} strokeWidth="1" opacity="0.5" />
            </>
          )}
          {mood === 'thinking' && (
             <g className="fill-amber-400">
                <circle cx="70" cy="95" r="6" className="animate-bounce" />
                <circle cx="100" cy="95" r="6" className="animate-bounce" style={{ animationDelay: '0.1s'}} />
                <circle cx="130" cy="95" r="6" className="animate-bounce" style={{ animationDelay: '0.2s'}} />
             </g>
          )}
        </g>

        {/* Improved Antenna */}
        <path d="M 100 40 L 100 20" stroke="#94a3b8" strokeWidth="8" strokeLinecap="round" />
        <circle cx="100" cy="15" r="8" fill={mood === 'thinking' ? '#f59e0b' : accentColor} className="animate-ping" />

        {mood === 'wave' && (
          <path d="M 170 110 Q 195 90 185 60" stroke="#f97316" strokeWidth="8" strokeLinecap="round" className="animate-bounce" />
        )}
      </g>
    </svg>
  );
};

export const NeuralProcessingView = ({ label, sublabel }: { label: string, sublabel?: string }) => (
  <div className="flex flex-col items-center justify-center p-12 text-center animate-fade-in relative min-h-[400px]">
    <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-20 dark:opacity-40">
       <div className="w-[340px] h-[340px] border-2 border-primary-500/30 rounded-full animate-spin-slow"></div>
       <div className="absolute w-[280px] h-[280px] border-2 border-dashed border-brand-500/30 rounded-full animate-reverse-spin opacity-50"></div>
    </div>

    <div className="relative mb-10 group">
