    const lowIssue = issue.toLowerCase();
    if (lowIssue.includes('gelap') || lowIssue.includes('cahaya') || lowIssue.includes('dark')) {
      return "Cari tempat yang lebih terang atau nyalakan lampu agar bodi mobil terlihat jelas.";
    }
    if (lowIssue.includes('buram') || lowIssue.includes('fokus') || lowIssue.includes('blur')) {
      return "Pastikan lensa kamera bersih dan mobil tidak bergerak saat difoto agar fokus terjaga.";
    }
    if (lowIssue.includes('mobil') || lowIssue.includes('bukan')) {
      return "Pastikan objek dalam foto adalah mobil Anda sesuai posisi yang diminta.";
    }
    return "Coba ambil foto ulang dengan pencahayaan yang lebih baik dan posisi yang stabil.";
  };

  const handleStnkUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const mimeType = file.type;
    setLoading(true);
    setLoadingType('STNK');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setSurvey((prev: any) => ({ ...prev, stnk: base64 }));
      const response = await extractStnkData(base64, mimeType);
      setLoading(false);
      setLoadingType(null);
      if (response.success && response.data) {
        setStnkResult({
          ownerName: response.data.owner || 'TIDAK TERDETEKSI',
          plate: response.data.plate || 'TIDAK TERDETEKSI',
          vin: response.data.vin || 'TIDAK TERDETEKSI',
          engine: response.data.engine || 'TIDAK TERDETEKSI',
          color: response.data.color || 'TIDAK TERDETEKSI',
          year: response.data.year || vehicle.year.toString(),
          status: response.data.status
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handlePhotoUpload = async (file: File, slotId: string, slotLabel: string) => {
    if (!file) return;

    const localUrl = URL.createObjectURL(file);
    setSurvey((prev: any) => ({ ...prev, photos: { ...prev.photos, [slotId]: localUrl } }));

    const reader = new FileReader();
    reader.onload = async (e) => {
      const base64 = e.target?.result as string;
      setSurvey((prev: any) => ({ ...prev, photos: { ...prev.photos, [slotId]: base64 } }));

      setPhotoValidation(prev => ({ ...prev, [slotId]: { status: 'LOADING' } }));
      try {
        const result = await validateVehiclePhoto(base64, slotLabel);
        setPhotoValidation(prev => ({ 
          ...prev, 
          [slotId]: { 
            status: result.valid ? 'VALID' : 'INVALID', 
            msg: result.issue,
            recommendation: result.valid ? undefined : getRecommendation(result.issue || '')
          } 
        }));
      } catch (e) {
        setPhotoValidation(prev => ({ ...prev, [slotId]: { status: 'VALID' } }));
      }
    };
    reader.readAsDataURL(file);
  };

  const runSurveyAI = async () => {
    const photoEntries = Object.entries(survey.photos).map(([id, data]) => ({ id, data: data as string }));
    if (photoEntries.length < 5) {
      alert("Yuk, lengkapi dulu ke-5 foto mobilnya ya.");
      return;
    }

    setLoading(true);
    setLoadingType('SURVEY');

    const expectedData = {
      brand: vehicle.brand,
      model: vehicle.model,
      color: stnkResult?.color || "Sesuai Data",
      plate: vehicle.plate
    };

    try {
      const response = await analyzeVehicleSurvey(photoEntries, expectedData);
      setLoading(false);
      setLoadingType(null);

      if (response.success) {
        const finalScore = response.score || 0;
        const isRejected = response.auditVerdict === 'REJECTED';
        const needsManual = (finalScore < 80 || response.auditVerdict === 'REVIEW_REQUIRED') && !isRejected;

        if (response.photoFlags) {
          const newVal: Record<string, any> = { ...photoValidation };
          response.photoFlags.forEach(flag => {
            if (flag.status !== 'OK') {
              newVal[flag.id] = {
                status: 'INVALID',
                msg: flag.reason,
                recommendation: getRecommendation(flag.status === 'DARK_PHOTO' ? 'gelap' : flag.reason)
              };
            }
          });
          setPhotoValidation(newVal);
        }

        setSurvey((prev: any) => ({ 
          ...prev, 
          score: finalScore, 
          summary: response.summary || '',
          underwritingReport: response.underwritingReport || '',
          detailedIssues: response.detailedIssues || [],
          photoFlags: response.photoFlags || [],
          verdict: isRejected ? 'REJECTED' : (needsManual ? 'MANUAL_REQUIRED' : 'CLEAN'),
          rejectionReason: response.rejectionReason || (isRejected ? 'Mobil sepertinya tidak sesuai dengan data STNK.' : ''),
          isDirty: response.isDirty || false,
          cleanlinessComment: response.cleanlinessComment || '',
          manualVerif: needsManual
        }));
      }
    } catch (err) {
      setLoading(false);
      setLoadingType(null);
      alert("Gagal menghubungkan ke server AI. Coba lagi ya.");
    }
  };

  const photoSlots = [
    { id: 'front', label: 'Depan Serong', desc: 'Sisi depan mobil' },
    { id: 'back', label: 'Belakang Serong', desc: 'Sisi belakang mobil' },
    { id: 'right', label: 'Sisi Kanan', desc: 'Samping kanan' },
    { id: 'left', label: 'Sisi Kiri', desc: 'Samping kiri' },
    { id: 'interior', label: 'Dashboard', desc: 'Bagian dalam mobil' }
  ];

  const capturedCount = Object.keys(survey.photos).length;

  const verdictData: any = {
    'CLEAN': { icon: ShieldCheck, color: 'text-emerald-500', bg: 'bg-emerald-500/10', label: 'AUDIT LOLOS', desc: 'Skor asuransi Anda dalam batas aman. Polis bisa langsung aktif.' },
    'REVIEW_REQUIRED': { icon: ActivityIcon, color: 'text-amber-500', bg: 'bg-amber-500/10', label: 'BUTUH REVIEW', desc: 'Ada sedikit ketidaksesuaian. Tim kami akan mengecek foto Anda secara manual.' },
    'MANUAL_REQUIRED': { icon: FileSearch, color: 'text-amber-600', bg: 'bg-amber-600/10', label: 'AUDIT MANUAL', desc: 'Skor di bawah 80. Perlu survei fisik atau video call untuk verifikasi.' },
    'REJECTED': { icon: ShieldX, color: 'text-rose-500', bg: 'bg-rose-500/10', label: 'DITOLAK', desc: 'Terdeteksi ketidaksesuaian identitas atau kondisi unit yang tidak layak asuransi.' },
  };

  return (
    <PageTransition>
      <div className="space-y-6 pb-24">
        <div className="px-2">
           <h2 className="text-2xl font-black uppercase tracking-tighter">Cek Kondisi <span className="text-primary-500">Mobil</span></h2>
           <p className="text-xs text-gray-500 font-medium mt-1">Langkah ini wajib untuk memastikan mobilmu mulus.</p>
        </div>

        {!survey.stnk ? (
          <div className="p-6 bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 rounded-[2.5rem] space-y-6 shadow-xl relative overflow-hidden">
              <div className="flex items-center gap-4 mb-2">
                  <div className="w-10 h-10 bg-primary-500/10 rounded-xl flex items-center justify-center text-primary-500 shadow-inner"><FileText size={20}/></div>
                  <div><h4 className="text-[0.7rem] font-black uppercase tracking-[0.2em]">Registrasi STNK AI</h4><p className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">Ekstraksi Dokumen Neural</p></div>
              </div>
              <label className="group relative aspect-[3/1] rounded-[2rem] border-2 border-dashed border-gray-300 dark:border-white/10 flex flex-col items-center justify-center gap-2 cursor-pointer hover:border-primary-500/50 transition-all bg-gray-50 dark:bg-white/[0.02]">
                  {loading && loadingType === 'STNK' ? <ScannerOverlay label="Audit STNK AI" /> : (
                  <>
                      <div className="flex gap-3">
                        <FileSearch size={32} className="text-gray-300 group-hover:text-primary-500 transition-colors"/>
                        <ImagePlus size={32} className="text-gray-300 group-hover:text-primary-500 transition-colors"/>
                      </div>
                      <p className="text-[0.6rem] font-black uppercase tracking-[0.2em] text-gray-500">Scan / Unggah STNK</p>
                      <input type="file" accept="image/*,application/pdf" className="hidden" onChange={handleStnkUpload} />
                  </>
                  )}
              </label>
          </div>
        ) : (
          <div className="flex items-center justify-between p-4 bg-emerald-500/10 rounded-2xl border border-emerald-500/20">
              <div className="flex items-center gap-3">
                  <div className="p-2 bg-emerald-500 rounded-lg text-white"><Check size={14} strokeWidth={3}/></div>
                  <span className="text-[0.6rem] font-black text-emerald-800 dark:text-emerald-200 uppercase tracking-widest">Dokumen Terverifikasi: {stnkResult.plate}</span>
              </div>
              <button onClick={() => setSurvey({...survey, stnk: null})} className="text-gray-400 hover:text-rose-500 transition-colors"><Trash2 size={16}/></button>
          </div>
        )}

        <div className="p-5 bg-blue-50 dark:bg-blue-900/10 rounded-[2rem] border border-blue-100 flex gap-4">
           <div className="w-10 h-10 bg-blue-500/10 rounded-xl flex items-center justify-center text-blue-500 flex-shrink-0">
              <Info size={20}/>
           </div>
           <p className="text-[0.7rem] font-medium text-blue-800 dark:text-blue-200 leading-relaxed">
              Ambil foto mobil dalam keadaan <span className="font-black">bersih & terang</span> ya. AI kami akan mengecek <span className="font-black">Kebersihan, Bodi, Kaca, dan Lampu</span>.
           </p>
        </div>

        <div className="grid grid-cols-2 gap-4">
           {photoSlots.map((slot) => {
              const val = photoValidation[slot.id];
              const hasPhoto = !!survey.photos[slot.id];
              return (
              <div key={slot.id} className="space-y-2">
                <div className={`group relative aspect-video rounded-[2rem] border-2 border-dashed transition-all flex flex-col items-center justify-center p-4 text-center overflow-hidden shadow-sm ${hasPhoto ? (val?.status === 'INVALID' ? 'border-rose-500 bg-rose-50' : 'border-primary-500 bg-primary-50') : 'border-gray-200 bg-white dark:bg-white/5'}`}>
                  {hasPhoto ? (
                    <>
                        <img src={survey.photos[slot.id]} className="absolute inset-0 w-full h-full object-cover rounded-[1.8rem]" alt={slot.label} />

                        {val?.status === 'LOADING' && (
                          <div className="absolute inset-0 bg-black/60 flex flex-col items-center justify-center text-white gap-2">
                              <Loader2 size={24} className="animate-spin text-primary-500"/>
                              <span className="text-[0.5rem] font-black uppercase tracking-widest">Memindai...</span>
                          </div>
                        )}

                        {val?.status === 'INVALID' && (
                          <div className="absolute inset-0 bg-rose-500/80 flex flex-col items-center justify-center text-white p-3 text-center">
                              <AlertTriangle size={20} className="mb-1"/>
                              <span className="text-[0.5rem] font-black uppercase leading-tight">{val.msg || 'Perlu Foto Ulang'}</span>
                          </div>
                        )}

                        <button 
                          onClick={() => { const n = {...survey.photos}; delete n[slot.id]; setSurvey({...survey, photos: n, score: 0}); }} 
                          className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center text-white rounded-[1.8rem] z-30"
                        >
                          <Trash2 size={24}/>
                        </button>

                        <div className="absolute top-2 left-3 px-2 py-0.5 bg-black/60 text-white rounded-full text-[0.45rem] font-black uppercase z-20">{slot.label}</div>
                    </>
                  ) : (
                    <>
                        <Camera size={24} className="text-gray-300 mb-2 group-hover:text-primary-500 transition-colors"/>
                        <p className="text-[0.6rem] font-black uppercase text-gray-500 tracking-tight">{slot.label}</p>
                        <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={(e) => { const f = e.target.files?.[0]; if (f) handlePhotoUpload(f, slot.id, slot.desc); }} />
                    </>
                  )}
                </div>
                {hasPhoto && val?.status === 'INVALID' && val.recommendation && (
                   <div className="p-2.5 bg-rose-50 dark:bg-rose-950/20 rounded-xl border border-rose-100 dark:border-rose-900/30 flex gap-2 animate-fade-in">
                      <Lightbulb size={12} className="text-rose-500 flex-shrink-0 mt-0.5"/>
                      <p className="text-[0.55rem] font-bold text-rose-800 dark:text-rose-300 leading-tight">
                         {val.recommendation}
                      </p>
                   </div>
                )}
              </div>
           )})}
        </div>

        {capturedCount === 5 && (
           <div className="space-y-6 pt-2 animate-pop-in">
              {loading ? (
                <div className="p-10 bg-white dark:bg-white/5 rounded-[3rem] shadow-xl text-center space-y-6">
                   <div className="relative inline-block">
                      <div className="absolute inset-0 bg-primary-500/20 blur-3xl rounded-full"></div>
                      <Cpu size={48} className="text-primary-500 animate-spin mx-auto relative z-10" />
                   </div>
                   <div className="space-y-2">
                      <p className="text-[0.7rem] font-black uppercase text-primary-500 tracking-[0.2em] animate-pulse">Audit Neural Aktif</p>
                      <p className="text-xs text-gray-500 font-medium italic">"Mengecek integritas panel & kebersihan unit..."</p>
                   </div>
                </div>
              ) : survey.score > 0 ? (
                <div className="space-y-4">
                   {survey.isDirty && (
                      <div className="p-6 bg-amber-50 dark:bg-amber-900/10 border-2 border-amber-200 dark:border-amber-800 rounded-[2.5rem] flex gap-4 animate-pop-in">
                         <div className="w-12 h-12 bg-amber-500 rounded-2xl flex items-center justify-center text-white flex-shrink-0 shadow-lg">
                            <Droplets size={24}/>
                         </div>
                         <div className="space-y-1">
                            <h4 className="text-sm font-black uppercase text-amber-800 dark:text-amber-400 leading-tight">Mobil Terdeteksi Kotor!</h4>
                            <p className="text-[0.65rem] font-bold text-amber-700 dark:text-amber-300 leading-relaxed uppercase tracking-tight">
                               {survey.cleanlinessComment || "AI mendeteksi kotoran yang dapat menutupi goresan. Disarankan cuci mobil dan foto ulang."}
                            </p>
                            <button 
                               onClick={() => setSurvey({...survey, photos: {}, score: 0})}
                               className="mt-2 text-[0.6rem] font-black text-amber-600 underline uppercase tracking-widest"
                            >
                               Foto Ulang Sekarang
                            </button>
                         </div>
                      </div>
                   )}

                   <div className={`p-8 bg-white dark:bg-white/5 border rounded-[3rem] shadow-xl space-y-6 animate-pop-in ${survey.verdict === 'CLEAN' ? 'border-emerald-500/20' : 'border-amber-500/20'}`}>
                      <div className="flex items-center gap-6">
                         <div className="relative w-24 h-24 flex items-center justify-center">
                            <svg className="w-full h-full transform -rotate-90">
                               <circle cx="48" cy="48" r="42" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-gray-100 dark:text-gray-800"/>
                               <circle cx="48" cy="48" r="42" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={263.8} strokeDashoffset={263.8 - (263.8 * survey.score) / 100} className={`transition-all duration-1000 ${survey.score >= 80 ? 'text-emerald-500' : 'text-amber-500'}`}/>
                            </svg>
                            <span className="absolute text-xl font-black">{survey.score}</span>
                         </div>
                         <div>
                            <p className="text-[0.6rem] font-bold text-gray-400 uppercase tracking-widest">Skor Audit AI</p>
                            <h4 className={`text-lg font-black uppercase ${survey.verdict === 'CLEAN' ? 'text-emerald-600' : 'text-amber-600'}`}>
                               {survey.verdict === 'CLEAN' ? 'Mobil Lolos Audit!' : 'Butuh Review Manual'}
                            </h4>
                            <p className="text-[0.65rem] text-gray-500 font-bold uppercase mt-1 tracking-tight">{survey.summary}</p>
                         </div>
                      </div>
                      <div className="p-5 bg-gray-50 dark:bg-black/20 rounded-2xl text-[0.65rem] font-medium leading-relaxed italic text-gray-600 dark:text-gray-300 border border-black/5">
                         <span className="font-black text-primary-500 uppercase not-italic block mb-1 tracking-widest text-[0.5rem]">Catatan Analis AI:</span>
                         "{survey.underwritingReport}"
                      </div>
                      <div className="flex items-center gap-2 text-emerald-600 dark:text-emerald-400">
                         <CheckCircle2 size={16}/>
                         <span className="text-[0.6rem] font-black uppercase tracking-widest">Audit Selesai. Klik Lanjut.</span>
                      </div>
                   </div>
                </div>
              ) : (
                <button 
                  onClick={runSurveyAI} 
                  className="w-full py-6 bg-slate-900 dark:bg-white text-white dark:text-black rounded-[2rem] font-black uppercase text-sm shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4 group"
                >
                   <BrainCircuit size={24} className="group-hover:rotate-12 transition-transform text-primary-500"/> 
                   Luncurkan Audit AI
                </button>
              )}
           </div>
        )}
      </div>
    </PageTransition>
  );
};

