// --- DB INTERFACES ---

export interface User {
  id?: number;
  email: string;
  name: string;
  phone: string;
  passwordHash?: string;
  salt?: string;
  role: UserRole;
  nodeId: string;
  ktp?: string;
  address?: string;
  trustScore: number;
  memberSince: string;
  verified: boolean;
}

export interface Policy {
  id?: number;
  userId: number;
  type: 'CAR' | 'TRAVEL' | 'PA' | 'MPAR';
  status: 'ACTIVE' | 'PENDING' | 'EXPIRED' | 'CANCELLED';
  startDate: string;
  endDate: string;
  premium: number;
  coverageDetails: any; // Menyimpan data input wizard (Vehicle, KYC, Survey)
  providerId: string;
  policyNumber: string;
  createdAt: string;
}

export interface Claim {
  id?: number;
  policyId?: number;
  userId: number;
  date: string;
  time: string;
  location: string;
  chronology: string;
  thirdPartyInvolved: boolean;
  status: 'SUBMITTED' | 'ANALYZING' | 'APPROVED' | 'REJECTED' | 'PAID';
  amountEstimated: number;
  amountApproved?: number;
  photos: string[]; // Base64 strings
  aiAnalysis?: any;
  createdAt: string;
}

export interface Transaction {
  id?: number;
  userId: number;
  type: 'PAYMENT' | 'COMMISSION' | 'WITHDRAWAL' | 'CLAIM_PAYOUT' | 'POINTS';
  amount: number;
  status: 'SUCCESS' | 'PENDING' | 'FAILED';
  description: string;
  date: string;
  referenceId?: string;
}

// Fix: Using named import for Dexie class to ensure constructor and instance methods like 'version' are correctly recognized by the compiler
export class SurePathDB extends Dexie {
  users!: Table<User, number>;
  policies!: Table<Policy, number>;
  claims!: Table<Claim, number>;
  transactions!: Table<Transaction, number>;

  constructor() {
    super('SurePathDB');
    // Fix for line 74: Ensure version() method is called on the Dexie instance
    this.version(3).stores({
      users: '++id, &email, nodeId, role, verified',
      policies: '++id, userId, type, status, policyNumber, createdAt',
      claims: '++id, userId, policyId, status, createdAt',
      transactions: '++id, userId, type, date, referenceId'
    });
  }
}

